#include <string>
using namespace std;

class Solution {
public:
    int maxPower(string s) {
        int maxLen = 1, curLen = 1;
        for (int i = 1; i < s.size(); i++) {
            if (s[i] == s[i - 1]) {
                curLen++;
                maxLen = max(maxLen, curLen);
            } else {
                curLen = 1;
            }
        }
        return maxLen;
    }
};
